import java.io.IOException;
import java.net.URI;
import java.net.URLEncoder;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) throws Exception {
        ConfigKey config = new ConfigKey("dev", "DEFAULT_GROUP", "order-service.yaml");
        Instance instance = new Instance("order-service", "DEFAULT_GROUP", "HZ", "127.0.0.1", 8080, true);

        URI configUri = URI.create("http://127.0.0.1:8848/nacos/v2/cs/config?" + encode(Map.of(
                "namespaceId", config.namespaceId,
                "group", config.group,
                "dataId", config.dataId)));
        String registerBody = encode(instance.toForm());
        HttpRequest registerRequest = HttpRequest.newBuilder(URI.create("http://127.0.0.1:8848/nacos/v2/ns/instance"))
                .timeout(Duration.ofMillis(300))
                .header("Content-Type", "application/x-www-form-urlencoded")
                .POST(HttpRequest.BodyPublishers.ofString(registerBody))
                .build();

        System.out.println("configKey=" + config.namespaceId + "/" + config.group + "/" + config.dataId);
        System.out.println("registerBody=" + registerBody);
        assert registerBody.contains("serviceName=order-service");
        assert registerBody.contains("ephemeral=true");

        HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofMillis(300)).build();
        try {
            HttpRequest configRequest = HttpRequest.newBuilder(configUri).timeout(Duration.ofMillis(300)).GET().build();
            HttpResponse<String> response = client.send(configRequest, HttpResponse.BodyHandlers.ofString());
            System.out.println("nacosAvailable=true, status=" + response.statusCode());
        } catch (IOException unavailable) {
            System.out.println("nacosAvailable=false, reason=" + unavailable.getClass().getSimpleName());
        }

        try {
            client.send(registerRequest, HttpResponse.BodyHandlers.ofString());
        } catch (IOException unavailable) {
            System.out.println("registerSkipped=true, reason=" + unavailable.getClass().getSimpleName());
        }
    }

    static String encode(Map<String, String> values) {
        return values.entrySet().stream()
                .map(entry -> url(entry.getKey()) + "=" + url(entry.getValue()))
                .collect(Collectors.joining("&"));
    }

    static String url(String value) {
        return URLEncoder.encode(value, StandardCharsets.UTF_8);
    }

    static final class ConfigKey {
        final String namespaceId;
        final String group;
        final String dataId;

        ConfigKey(String namespaceId, String group, String dataId) {
            this.namespaceId = namespaceId;
            this.group = group;
            this.dataId = dataId;
        }
    }

    static final class Instance {
        final String serviceName;
        final String groupName;
        final String clusterName;
        final String ip;
        final int port;
        final boolean ephemeral;

        Instance(String serviceName, String groupName, String clusterName, String ip, int port, boolean ephemeral) {
            this.serviceName = serviceName;
            this.groupName = groupName;
            this.clusterName = clusterName;
            this.ip = ip;
            this.port = port;
            this.ephemeral = ephemeral;
        }

        Map<String, String> toForm() {
            Map<String, String> form = new LinkedHashMap<>();
            form.put("serviceName", serviceName);
            form.put("groupName", groupName);
            form.put("clusterName", clusterName);
            form.put("ip", ip);
            form.put("port", String.valueOf(port));
            form.put("ephemeral", String.valueOf(ephemeral));
            form.put("metadata", "version=v1,zone=hz");
            return form;
        }
    }
}
